# 16 vertices: (g, i) for g in 0..3, i in 0..3
# Edges within each clique K4: 6 edges per clique
# Edges between consecutive cliques: 4 edges per pair

edges = []
for g in range(4):
    for i in range(4):
        for j in range(i+1, 4):
            edges.append(((g,i), (g,j)))
for g in range(3):
    for i in range(4):
        edges.append(((g,i), (g+1,i)))

print(f"Number of edges: {len(edges)}")

