for g in range(4):
    for i in range(4):
        adj[(g,i)] = []
for (u, v) in edges:
    adj[u].append(v)
    adj[v].append(u)

# Try backtracking with good variable ordering
# Use the "most constrained variable" heuristic

def solve():
    labels = {}  # (g,i) -> label
    used_labels = set()
    used_diffs = set()

    # Order vertices by degree (all have same degree in this graph)
    # Let's try a specific ordering
    vertices = [(g, i) for g in range(4) for i in range(4)]

    def get_constraints(v):
        """Get the set of forbidden labels for vertex v based on already assigned neighbors."""
        forbidden = set()
        for neighbor in adj[v]:
            if neighbor in labels:
                nlabel = labels[neighbor]
                # The edge difference must not be used
                # So label(v) cannot be nlabel +/- d for any used diff d
                # Actually, we need: |label(v) - nlabel| not in used_diffs
                # So label(v) != nlabel +/- d for d in used_diffs
                for d in used_diffs:
                    forbidden.add(nlabel + d)
                    forbidden.add(nlabel - d)
                # Also label(v) != nlabel (distinct labels)
                forbidden.add(nlabel)
        return forbidden

    def backtrack(idx):
        if idx == 16:
            return True

        v = vertices[idx]
        forbidden = get_constraints(v)

        # Try labels in order, preferring those that create "interesting" edge differences
        candidates = [l for l in range(37) if l not in used_labels and l not in forbidden]

        # Sort candidates by some heuristic
        # Try to spread out the labels
        random.shuffle(candidates)

        for label in candidates:
            labels[v] = label
            used_labels.add(label)

            # Compute new edge differences
            new_diffs = []
            valid = True
            for neighbor in adj[v]:
                if neighbor in labels:
                    d = abs(label - labels[neighbor])
                    if d in used_diffs or d == 0:
                        valid = False
                        break
                    new_diffs.append(d)

            if valid:
                for d in new_diffs:
                    used_diffs.add(d)

                if backtrack(idx + 1):
                    return True

                for d in new_diffs:
                    used_diffs.discard(d)

            del labels[v]
            used_labels.discard(label)

        return False

    return backtrack(0)

